Import-Module "$PSScriptRoot\..\src\Settings.psm1" -Force
Test 'Defaults contain no fake data' { $s=Read-AppSettings (Join-Path $env:TEMP ([guid]::NewGuid().ToString()+'.json')); Assert-Equal $s.SchemaVersion 1; Assert-Equal @($s.Providers).Count 3; Assert-Equal $s.Providers[0].ManualSubscription $null }
Test 'Settings roundtrip and bad budget' {
 $dir=Join-Path $env:TEMP ([guid]::NewGuid().ToString()); $path=Join-Path $dir 'settings.json'
 try { $s=Read-AppSettings $path; $s.Providers[0].ApiMonthlyBudgetUsd=100; Write-AppSettings $path $s; Assert-Equal (Read-AppSettings $path).Providers[0].ApiMonthlyBudgetUsd 100; $s.Providers[0].ApiMonthlyBudgetUsd=-1; Assert-Throws { Write-AppSettings $path $s } } finally { if (Test-Path $dir) { Remove-Item -LiteralPath $dir -Recurse -Force } }
}
Test 'Broken settings preserved' { $path=Join-Path $env:TEMP ([guid]::NewGuid().ToString()+'.json'); try { [IO.File]::WriteAllText($path,'broken'); Assert-Throws { Read-AppSettings $path }; Assert-Equal ([IO.File]::ReadAllText($path)) 'broken' } finally { Remove-Item -LiteralPath $path -Force } }
Test 'Protected secret roundtrip' { $dir=Join-Path $env:TEMP ([guid]::NewGuid().ToString()); try { Save-ProviderSecret 'codex' (ConvertTo-SecureString 'test-secret-123' -AsPlainText -Force) $dir; $s=Read-ProviderSecret 'codex' $dir; Assert-True ($s -is [securestring]); Assert-True (-not ([IO.File]::ReadAllText((Join-Path $dir 'codex.secret')).Contains('test-secret-123'))) } finally { if (Test-Path $dir) { Remove-Item -LiteralPath $dir -Recurse -Force } } }
Test 'Orientation migration and persistence' { $dir=Join-Path $env:TEMP ([guid]::NewGuid().ToString());$path=Join-Path $dir 'settings.json';try {$s=New-AppSettings;Assert-Equal $s.Orientation 'vertical';$s.Remove('Orientation');Write-AppSettings $path $s;$s=Read-AppSettings $path;Assert-Equal $s.Orientation 'vertical';$s.Orientation='horizontal';Write-AppSettings $path $s;Assert-Equal (Read-AppSettings $path).Orientation 'horizontal';$s.Orientation='diagonal';Assert-Throws {Write-AppSettings $path $s}} finally {if (Test-Path $dir) {Remove-Item -LiteralPath $dir -Recurse -Force}} }
Test 'Layout clone does not invalidate consumption data' { $s=New-AppSettings;$s.Providers[0].ApiMonthlyBudgetUsd=100;$clone=ConvertTo-AppHashtable (ConvertFrom-Json ($s | ConvertTo-Json -Depth 12));$clone.Orientation='horizontal';$clone.Providers[0].ApiMonthlyBudgetUsd=[double]100;Assert-Equal (Test-ProviderSettingsChanged $s $clone) $false;$clone.Providers[0].ApiMonthlyBudgetUsd=50;Assert-True (Test-ProviderSettingsChanged $s $clone) }
